var mainEdges = [];
var branchEdges = [];

function addMainEdge(id, fromId, toId, labelNum, labelDen, labelX) {
  var a = nodes[fromId], b = nodes[toId];
  var x1 = a.x - a.r - 5;
  var x2 = b.x + b.r + 5;
  var ln = edgeGroup.line(x1, a.y, x2, b.y)
    .stroke({ color: black, width: 3.7, linecap: 'round' })
    .marker('end', arrowBlack);

  var e = { id: id, from: fromId, to: toId, x1: x1, y1: a.y, x2: x2, y2: b.y, line: ln };
  mainEdges.push(e);

  if (labelNum && labelDen) {
    fraction(labelGroup, labelX || ((x1 + x2) / 2), 117, labelNum, labelDen, 31, {
      minWidth: 58,
      background: true,
      padX: 3,
      padY: 1,
      bgOpacity: 0.96
    });
  }
  return e;
}

addMainEdge('loss-f3', 'loss', 'f3', null, null);
addMainEdge('f3-h3', 'f3', 'h3', '∂f₃', '∂h₃', 1608);
addMainEdge('h3-f2', 'h3', 'f2', '∂h₃', '∂f₂', 1380);
addMainEdge('f2-h2', 'f2', 'h2', '∂f₂', '∂h₂', 1151);
addMainEdge('h2-f1', 'h2', 'f1', '∂h₂', '∂f₁', 920);
addMainEdge('f1-h1', 'f1', 'h1', '∂f₁', '∂h₁', 685);
addMainEdge('h1-f0', 'h1', 'f0', '∂h₁', '∂f₀', 435);

function addBranch(parentId, childId, num, den, labelX, labelY) {
  var p = nodes[parentId], c = nodes[childId];
  var left = c.x < p.x;
  var x1 = p.x + (left ? -22 : 22);
  var y1 = p.y + p.r * 0.84;
  var x2 = c.x + (left ? 25 : -25);
  var y2 = c.y - c.r * 0.83;

  var ln = edgeGroup.line(x1, y1, x2, y2)
    .stroke({ color: black, width: 3.5, linecap: 'round' })
    .marker('end', arrowBlack);

  var lab = fraction(labelGroup, labelX, labelY, num, den, 38, {
    minWidth: 72,
    background: true,
    padX: 3,
    padY: 1,
    bgOpacity: 0.93
  });

  var br = {
    id: parentId + '-' + childId,
    parent: parentId,
    child: childId,
    x1: x1,
    y1: y1,
    x2: x2,
    y2: y2,
    line: ln,
    label: lab
  };
  branchEdges.push(br);
  return br;
}

[0, 1, 2, 3].forEach(function (k) {
  var f = 'f' + k, sx = xpos[f], sk = sub(k);
  addBranch(f, 'b' + k, '∂f' + sk, '∂β' + sk, sx - 112, 146);
  addBranch(f, 'w' + k, '∂f' + sk, '∂ω' + sk, sx + 112, 146);
});

Object.keys(nodes).forEach(function (id) {
