  fraction(labelGroup, nodes['b' + k].x, nodes['b' + k].y - 4, '∂ℓᵢ', '∂β' + sk, 40, { minWidth: 76 });
  fraction(labelGroup, nodes['w' + k].x, nodes['w' + k].y - 4, '∂ℓᵢ', '∂ω' + sk, 40, { minWidth: 76 });
});

function readable(id) {
  if (id === 'x') return 'xᵢ';
  if (id === 'loss') return 'ℓᵢ';
  if (id.charAt(0) === 'f') return '∂ℓᵢ/∂f' + sub(id.slice(1));
  if (id.charAt(0) === 'h') return '∂ℓᵢ/∂h' + sub(id.slice(1));
  if (id.charAt(0) === 'b') return '∂ℓᵢ/∂β' + sub(id.slice(1));
  if (id.charAt(0) === 'w') return '∂ℓᵢ/∂ω' + sub(id.slice(1));
  return id;
}

function nodeTip(id) {
  if (id === 'x') {
    return 'xᵢ is intentionally isolated here: this is the backward derivative graph, not the forward activation graph.';
  }
  if (id === 'loss') {
    return 'The scalar loss ℓᵢ is the right-hand starting point for the backward derivative chain.';
  }
  var n = nodes[id];
  if (n.kind === 'param') {
    return readable(id) + ' branches from ' + readable(n.parent) + ' using the local derivative for this parameter.';
  }
  return readable(id) + ' reuses the downstream gradient to its right and multiplies by the local derivative on the connecting arrow.';
}

Object.keys(nodes).forEach(function (id) {
  var n = nodes[id];
  hitGroup.circle(n.r * 2 + 18).center(n.x, n.y)
    .fill({ color: '#fff', opacity: 0.001 })
