});

function focusCircle(id, strong) {
  var n = nodes[id];
  focusGroup.circle((n.r + (strong ? 8 : 5)) * 2).center(n.x, n.y)
    .fill('none')
    .stroke({ color: black, width: strong ? 6.5 : 4.8, opacity: strong ? 0.36 : 0.22 });
}

function focusLine(e, strong) {
  if (!e) return;
  focusGroup.line(e.x1, e.y1, e.x2, e.y2)
    .stroke({ color: black, width: strong ? 8.5 : 6.4, opacity: strong ? 0.28 : 0.18, linecap: 'round' })
    .marker('end', arrowFocus);
}

function findMain(id) {
  for (var i = 0; i < mainEdges.length; i++) {
    if (mainEdges[i].id === id) return mainEdges[i];
  }
  return null;
}

function findBranch(id) {
  for (var i = 0; i < branchEdges.length; i++) {
    if (branchEdges[i].id === id) return branchEdges[i];
  }
  return null;
}

function focusBranch(b, strong) {
  if (!b) return;
  focusGroup.line(b.x1, b.y1, b.x2, b.y2)
    .stroke({ color: black, width: strong ? 8 : 6, opacity: strong ? 0.30 : 0.18, linecap: 'round' })
    .marker('end', arrowFocus);
  focusCircle(b.child, strong);
  setFractionColor(b.label, black);
}

