  }
];

function resetBranchLabelColors() {
  branchEdges.forEach(function (b) { setFractionColor(b.label, black); });
}

function renderFocus() {
  focusGroup.clear();
  resetBranchLabelColors();

  if (currentFocus === 'Chain to ∂ℓ_i/∂h_2') {
    ['loss', 'f3', 'h3', 'f2', 'h2'].forEach(function (id) {
      focusCircle(id, id === 'h2');
    });
    ['loss-f3', 'f3-h3', 'h3-f2', 'f2-h2'].forEach(function (id) {
      focusLine(findMain(id), id === 'f2-h2');
    });
  } else if (currentFocus === 'Branches from ∂ℓ_i/∂f_2') {
    ['loss', 'f3', 'h3', 'f2'].forEach(function (id) {
      focusCircle(id, id === 'f2');
    });
    ['loss-f3', 'f3-h3', 'h3-f2'].forEach(function (id) {
      focusLine(findMain(id), false);
    });
    focusBranch(findBranch('f2-b2'), true);
