function syncUI() {
  var sel = document.getElementById('dependencyFocusInput');
  if (sel) sel.value = currentFocus;

  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');

  if (narr) narr.textContent = demoSteps[currentStep].narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length;
}

function update_dependencyFocus(v) {
  currentFocus = v || 'Clean source graph';
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.dependencyFocus === currentFocus) {
      currentStep = i;
      break;
    }
  }
  syncUI();
  renderFocus();
}

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  currentFocus = demoSteps[currentStep].state.dependencyFocus;
  syncUI();
  renderFocus();
}

function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

